// Normaliza o payload da Evolution. Trata apenas TEXTO e ÁUDIO —
// imagem, documento, sticker, localização etc. são ignorados de propósito.
const raw = $input.first().json.body || $input.first().json;
const data = raw.data || raw;
const key = data.key || {};

// Ignora mensagens enviadas por nós mesmos.
if (key.fromMe === true) {
  return [];
}

const semSufixo = function (jid) { return (jid || '').replace(/@.*$/, ''); };
const ehLid = function (jid) { return typeof jid === 'string' && jid.endsWith('@lid'); };

// Número real do remetente. Com a migração do WhatsApp para LID, o
// remoteJid pode vir como "<id>@lid" (identificador opaco, não telefone).
// Nesse caso o telefone vem em senderPn / remoteJidAlt.
let numero = '';
for (const cand of [key.senderPn, key.remoteJidAlt, key.remoteJid]) {
  if (cand && !ehLid(cand)) {
    numero = semSufixo(cand).replace(/\D/g, '');
    if (numero) break;
  }
}

// Identificador LID — identidade estável do contato no novo modelo do
// WhatsApp. Guardado na 1ª resposta para casar conversas futuras.
let lid = '';
for (const cand of [key.remoteJid, key.remoteJidAlt, key.previousRemoteJid, key.senderLid, key.participantLid]) {
  if (ehLid(cand)) { lid = semSufixo(cand); break; }
}

// Sem telefone e sem LID não há como identificar o remetente.
if (!numero && !lid) return [];

const msg = data.message || {};
let tipo = 'desconhecido';
let conteudo = null;
let mimetype = null;

if (msg.conversation) {
  tipo = 'texto';
  conteudo = msg.conversation;
} else if (msg.extendedTextMessage?.text) {
  tipo = 'texto';
  conteudo = msg.extendedTextMessage.text;
} else if (msg.audioMessage) {
  tipo = 'audio';
  mimetype = msg.audioMessage.mimetype;
} else {
  // imagem, documento, sticker, localização, etc. — ignorados
  return [];
}

return [{
  json: {
    numero,
    lid,
    tipo,
    conteudo,
    mimetype,
    messageId: key.id,
    timestamp: data.messageTimestamp || Math.floor(Date.now() / 1000),
  },
}];

// Junta os dados da mensagem com os dados do cliente oculto ativo.
const msg = $('Normalizar mensagem').first().json;
const co = $input.first().json;
const eh_primeira_resposta = !co.primeira_resposta_em;

// Número para onde o Carlos responde: o do remetente quando há; senão o
// telefone cadastrado da clínica (caso a mensagem tenha vindo só com LID).
const soDig = function (s) { return (s || '').replace(/\D/g, ''); };
const numero_envio = msg.numero || soDig(co.clinica_whatsapp) || soDig(co.clinica_telefone);

return [{ json: { ...msg, ...co, eh_primeira_resposta, numero_envio } }];

// ───────────────────────────────────────────────────────────────────
// TODO — CONVERSÃO DE ÁUDIO (decidir como hospedar)
//
// O WhatsApp entrega áudio em ogg/opus; o OpenRouter (content do tipo
// input_audio) só aceita "mp3" ou "wav". Enquanto a conversão real não
// estiver ligada, a transcrição vai falhar para áudios de verdade.
//
// Para ligar, troque o passthrough abaixo por uma destas opções:
//   A) n8n self-hosted COM ffmpeg — nó Execute Command:
//        ffmpeg -i pipe:0 -f mp3 pipe:1
//   B) API externa (ex.: CloudConvert) — sobe o base64, converte p/ mp3.
// Em ambos os casos, devolva audio_base64 (mp3 em base64).
// ───────────────────────────────────────────────────────────────────
const base = $('Merge dados').first().json;
const base64 = $input.first().json.base64;

if (!base64) {
  throw new Error('Evolution nao retornou base64 do audio');
}

return [{
  json: {
    ...base,
    audio_base64: base64, // TODO: substituir pelo mp3 convertido
    audio_format: 'mp3',  // OpenRouter aceita 'mp3' ou 'wav'
  },
}];

